<?php
$meta = academic_meta($classroom);
$displayPeriods = $book['config']['periods'] ?? academic_periods();


$query = is_string($_GET['q'] ?? null) ? mb_strtolower(trim($_GET['q'])) : '';
$statusFilter = is_string($_GET['status'] ?? null) ? $_GET['status'] : '';
$periodFilter = !empty($book['config']['periods']) ? academic_selected_period() : '';
$detailParams = array_filter($_GET, fn($v) => is_scalar($v)); $detailParams['view'] = 'student';
$sort = is_string($_GET['sort'] ?? null) && in_array($_GET['sort'], ['name', 'highest', 'lowest'], true) ? $_GET['sort'] : 'name';
$filtered = array_values(array_filter($students, function ($student) use ($query, $statusFilter, $periodFilter, $rows) {
    $row = $rows[(int) $student['id']];
    $state = $periodFilter ? ($row['periods'][$periodFilter]['status'] ?? 'Not Graded') : $row['status'];
    return ($query === '' || str_contains(mb_strtolower($student['name']), $query)) && ($statusFilter === '' || $statusFilter === $state);
}));
usort($filtered, function ($a, $b) use ($rows, $sort, $periodFilter) {
    if ($sort === 'name') return [$a['name'], $a['id']] <=> [$b['name'], $b['id']];
    $value = fn($student) => $periodFilter ? ($rows[$student['id']]['periods'][$periodFilter]['overall'] ?? null) : $rows[$student['id']]['overall'];
    $av = $value($a); $bv = $value($b);
    if ($av === null || $bv === null) return ($av === null ? 1 : 0) <=> ($bv === null ? 1 : 0);
    return ($sort === 'highest' ? $bv <=> $av : $av <=> $bv) ?: ($a['id'] <=> $b['id']);
});
$size = in_array((int) ($_GET['per_page'] ?? 8), [8, 15, 30], true) ? (int) ($_GET['per_page'] ?? 8) : 8;
$studentPage = page_records($filtered, 'page', $size);
?>
<div class="academic-context"><span><?php echo esc(($meta['subject_code'] ?: $classroom['subject']) . ' | ' . $meta['academic_year'] . ' | ' . $meta['semester']); ?></span><a href="/QuizWeb/classroom_settings.php?classroom_id=<?php echo $classroomId; ?>">Class settings</a></div>
<?php if ($periodFilter): render_academic_period_navigation('/QuizWeb/gradebook.php', $periodFilter); endif; ?>
<section class="glass panel academic-gradebook academic-component-grid">
<div class="academic-panel-heading"><div><h2><?php echo $periodFilter ? esc(ucfirst($periodFilter)) . ' grade entry' : 'Component grade entry'; ?></h2><p>One row per student. Enter each component grade out of 100, then save this page.</p></div><a class="button button-secondary" href="<?php echo esc($url . '&view=setup'); ?>">Edit component weights</a></div>
<p class="academic-notice">Blank uses the calculated activity grade shown underneath, or stays ungraded if no score exists. An entered grade replaces the calculation for that component in this period. Clear it to restore the calculation.</p>
<form method="get" class="academic-filter-bar"><input type="hidden" name="classroom_id" value="<?php echo $classroomId; ?>"><input type="hidden" name="view" value="overview"><input type="hidden" name="period" value="<?php echo esc($periodFilter); ?>"><label><span>Search student</span><input type="search" name="q" value="<?php echo esc($query); ?>" placeholder="Student name"></label><label><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach (['Complete', 'Partial', 'Not Started', 'Not Graded', 'Missing'] as $state): ?><option <?php echo $statusFilter === $state ? 'selected' : ''; ?>><?php echo esc($state); ?></option><?php endforeach; ?></select></label><label><span>Sort</span><select name="sort"><?php foreach (['name' => 'Student name', 'highest' => 'Highest grade', 'lowest' => 'Lowest grade'] as $value => $label): ?><option value="<?php echo esc($value); ?>" <?php echo $sort === $value ? 'selected' : ''; ?>><?php echo esc($label); ?></option><?php endforeach; ?></select></label><label><span>Students per page</span><select name="per_page"><?php foreach ([8,15,30] as $limit): ?><option <?php echo $size === $limit ? 'selected' : ''; ?>><?php echo $limit; ?></option><?php endforeach; ?></select></label><button class="button button-secondary">Apply</button></form>
<?php if (!empty($book['locked'])): ?><p class="academic-notice">Grades are finalized. Reopen the release in Semester Summary to edit.</p><?php endif; ?>
<form method="post" class="stack-form" data-grade-dirty data-component-entry><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="component_scores"><input type="hidden" name="period_id" value="<?php echo esc($periodFilter ?: 'all'); ?>">
<div class="academic-table-scroll"><table class="academic-table academic-component-entry-table"><caption><?php echo esc($periodFilter ? ucfirst($periodFilter) . ' period' : 'Component grades'); ?> - <?php echo count($filtered); ?> students</caption><thead><tr><th scope="col">Student</th><?php foreach ($book['config']['categories'] as $category): ?><th scope="col"><?php echo esc($category['name']); ?><small><?php echo esc(grade_display($category['weight'])); ?>% weight / grade out of 100</small></th><?php endforeach; ?><th scope="col"><?php echo $periodFilter ? esc(ucfirst($periodFilter)) : 'Current'; ?> grade</th><th scope="col">Status</th></tr></thead><tbody>
<?php foreach ($studentPage['items'] as $student): $sid = (int) $student['id']; $periodRow = $periodFilter ? $rows[$sid]['periods'][$periodFilter] : $rows[$sid]; $componentRows = array_column($periodRow['categories'], null, 'id'); ?>
<tr><th scope="row"><strong><?php echo esc($student['name']); ?></strong><a class="academic-student-detail-link" href="<?php echo esc('/QuizWeb/gradebook.php?' . http_build_query(array_merge($detailParams, ['student_id' => $sid, 'period' => $periodFilter]))); ?>">Activities and details</a></th>
<?php foreach ($book['config']['categories'] as $category): $component = $componentRows[$category['id']] ?? []; $manual = $component['manual_grade']['value'] ?? null; $posted = $error && ($_POST['action'] ?? '') === 'component_scores' ? ($_POST['component_scores'][$sid][$category['id']] ?? null) : null; ?>
<td><label class="academic-component-input"><input aria-label="<?php echo esc($student['name'] . ' - ' . $category['name']); ?>" type="number" name="component_scores[<?php echo $sid; ?>][<?php echo esc($category['id']); ?>]" min="0" max="100" step="0.01" placeholder="<?php echo isset($component['automatic_percentage']) ? esc(grade_display($component['automatic_percentage'])) : 'Ungraded'; ?>" value="<?php echo esc(is_string($posted) ? $posted : ($manual === null ? '' : (string) $manual)); ?>" <?php echo !empty($book['locked']) ? 'disabled' : ''; ?>></label><small><?php echo $manual !== null ? 'Manual grade' : (isset($component['automatic_percentage']) ? 'Calculated: ' . esc(grade_display($component['automatic_percentage'])) : 'Enter grade'); ?></small></td>
<?php endforeach; ?><td><strong class="academic-grade-value"><?php echo esc(grade_display($periodRow['overall'])); ?></strong></td><td><span class="academic-status"><?php echo esc($periodRow['status']); ?></span></td></tr>
<?php endforeach; ?><?php if (!$filtered): ?><tr><td colspan="<?php echo count($book['config']['categories']) + 3; ?>">No students match these filters.</td></tr><?php endif; ?></tbody></table></div>
<?php if (empty($book['locked']) && $studentPage['items']): ?><label><span>Correction reason (required when changing a saved grade or published result)</span><input name="reason" maxlength="500" value="<?php echo esc($error && is_string($_POST['reason'] ?? null) ? $_POST['reason'] : ''); ?>"></label><div class="academic-save-bar"><p>Save before switching periods or pages. Students see changes after you publish the updated release.</p><button class="button button-primary">Save Changes</button></div><?php endif; ?></form>
<?php render_pagination($studentPage); ?>
</section>
<?php if (empty($book['locked'])): ?>
<section class="glass panel academic-add-component"><details <?php echo $error && ($_POST['action'] ?? '') === 'add_component' ? 'open' : ''; ?>><summary>Add grading component / Class Participation</summary><p>Add a separate column for every student. Class Participation is its own grading component with its own weight. Component definitions apply to all periods; entered grades stay in their selected period.</p><form method="post" class="stack-form" data-grade-dirty><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="add_component"><div class="split-fields"><label><span>New component name</span><input name="name" maxlength="50" required value="<?php echo esc(is_string($_POST['name'] ?? null) ? $_POST['name'] : (count(array_filter($book['config']['categories'], fn($c) => stripos($c['name'], 'participation') !== false)) ? '' : 'Class Participation')); ?>"></label><label><span>New component weight (%)</span><input name="weight" type="number" min="0.01" max="100" step="0.01" required value="<?php echo esc(is_string($_POST['weight'] ?? null) ? $_POST['weight'] : ''); ?>"></label></div><p>Adjust the existing weights so all components, including the new one, total 100%.</p><div class="academic-component-weight-fields"><?php foreach ($book['config']['categories'] as $category): ?><label><span><?php echo esc($category['name']); ?> (%)</span><input type="number" name="component_weights[<?php echo esc($category['id']); ?>]" min="0" max="100" step="0.01" required value="<?php echo esc(is_string($_POST['component_weights'][$category['id']] ?? null) ? $_POST['component_weights'][$category['id']] : (string) $category['weight']); ?>"></label><?php endforeach; ?></div><label><span>Reason for changing the grading components</span><input name="reason" maxlength="500" required value="<?php echo esc($error && is_string($_POST['reason'] ?? null) ? $_POST['reason'] : ''); ?>"></label><button class="button button-primary">Add Component Column</button></form></details></section>
<?php endif; ?>
<p class="academic-notice">For all three term grades, the semester final, and publishing, open <a href="<?php echo esc($url . '&view=semester&period=' . ($periodFilter ?: 'prelim')); ?>">Semester Summary</a>.</p>
